    internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();Window host=null;QuickPreviewPane pane=null;MainWindow main=null;Action<bool,string> check=(value,text)=>{if(!value)throw new Exception(text);log.Add(text);};
        try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs");FluentTheme.Ensure();AppearanceTheme.Apply("Light");
            string files=Directory.CreateDirectory(Path.Combine(root,"files")).FullName,video=Path.Combine(files,"01-silent.mp4"),other=Path.Combine(files,"02-video.mkv"),text=Path.Combine(files,"03-document.txt");File.WriteAllText(text,"Current document after cancelled video.");
            using(MediaProcess.Acquire()){MediaProcess.Run("ffmpeg.exe",new[]{"-v","error","-nostdin","-f","lavfi","-i","testsrc2=size=320x180:rate=12","-t","8","-an","-c:v","mpeg4","-pix_fmt","yuv420p","-y",video},CancellationToken.None,20);MediaProcess.Run("ffmpeg.exe",new[]{"-v","error","-nostdin","-i",video,"-c","copy","-y",other},CancellationToken.None,20);}
            var frames=VideoFrames.Load(video,CancellationToken.None,delegate{});check(frames.Count==6&&frames.All(x=>x.Image.IsFrozen),"silent video produces six frozen frame images without an audio requirement");check(frames.Select(x=>x.Seconds).SequenceEqual(new[]{.8,2,3.2,4.4,5.6,6.8},new Approximate()),"frames sample 10, 25, 40, 55, 70 and 85 percent of duration");check(frames.All(x=>x.Image.PixelWidth<=1280&&x.Image.PixelHeight<=720),"decoded preview images are bounded to 1280 x 720");
            int cacheCount=Directory.GetDirectories(VideoFrames.Root).Length;var cached=VideoFrames.Load(video,CancellationToken.None,delegate{});check(cached.Count==6&&Directory.GetDirectories(VideoFrames.Root).Length==cacheCount,"repeated preview reuses the complete cached frame set");
            File.SetLastWriteTimeUtc(video,DateTime.UtcNow.AddSeconds(2));VideoFrames.Load(video,CancellationToken.None,delegate{});check(Directory.GetDirectories(VideoFrames.Root).Length==cacheCount+1,"source timestamp changes invalidate the video cache");
            using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();bool stopped=false;try{VideoFrames.Load(video,cancelled.Token,delegate{});}catch(OperationCanceledException){stopped=true;}check(stopped,"cancelled requests do not start queued decoding");}
            pane=new QuickPreviewPane(delegate{});host=new Window{Content=pane,Width=760,Height=600};Open(host);pane.ShowFile(video);NavigationTests.Wait(pane.LoadingTask);host.UpdateLayout();check(pane.VideoCountForTests==6&&pane.VideoIndexForTests==0,"preview displays the filmstrip and selects the first frame");var first=pane.VideoImageForTests().Image;pane.SelectVideoFrame(4);host.UpdateLayout();check(pane.VideoIndexForTests==4&&!Object.ReferenceEquals(first,pane.VideoImageForTests().Image),"mouse-equivalent frame selection changes the enlarged picture");pane.VideoArrowForTests(Key.Right);check(pane.VideoIndexForTests==5,"right arrow advances a video frame");pane.VideoArrowForTests(Key.Right);check(pane.VideoIndexForTests==5,"frame selection stops at the last frame");pane.VideoArrowForTests(Key.Left);check(pane.VideoIndexForTests==4,"left arrow returns to the previous frame");NextStageTests.Draw(host,Path.Combine(root,"video-filmstrip.png"));
            pane.SetViewMode(PreviewMode.Hex);NavigationTests.Wait(pane.LoadingTask);check(pane.VideoCountForTests==0,"hex mode clears the filmstrip instead of mixing text and video");pane.SetViewMode(PreviewMode.Auto);NavigationTests.Wait(pane.LoadingTask);check(pane.VideoCountForTests==6,"automatic mode restores video frames from cache");
            string uncached=Path.Combine(root,"cancel-this.mp4");File.Copy(video,uncached);pane.ShowFile(uncached);var old=pane.LoadingTask;var until=DateTime.UtcNow.AddSeconds(15);while(pane.VideoCountForTests<1&&!old.IsCompleted&&DateTime.UtcNow<until)NavigationTests.Wait(Task.Delay(40));pane.ShowFile(text);NavigationTests.Wait(pane.LoadingTask);NavigationTests.Wait(old);host.UpdateLayout();check(pane.VideoCountForTests==0&&pane.VideoStatusForTests!=L.Text("video.generating"),"changing files cancels active video decoding without stale frame callbacks");check(!Directory.GetDirectories(VideoFrames.Root,"*.tmp").Any(),"cancelled work removes its partial frame directory");
            using(var remote=new RemoteConnection(new NetworkProfile{Protocol=NetworkProtocol.FTP,Host="fixture.invalid",Port=21,UserName="fixture"})){typeof(RemoteConnection).GetField("login",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(remote,remote.Options("test-only"));pane.ShowRemoteFile("/movie.mp4",remote,"1");check(pane.VideoConsentForTests&&pane.VideoCountForTests==0,"remote video shows an explicit download action without decoding or opening the connection");int revision=pane.LoadVersion;pane.ShowRemoteFile("/movie.mp4",remote,"1");check(pane.LoadVersion==revision,"unchanged remote selection does not reset its consent state");pane.ShowRemoteFile("/movie.mp4",remote,"2");check(pane.LoadVersion>revision,"changed remote metadata invalidates prior preview state");NextStageTests.Draw(host,Path.Combine(root,"remote-video-consent.png"));}
            pane.DisposePreview();host.Close();host=null;pane=null;
            main=new MainWindow(files,new ProgramSettings{AutoRefresh=false}){Width=1400,Height=900};Open(main);NavigationTests.WaitPanels(main);var panel=FluentUiTests.Children<FilePanel>(main).First();panel.MarkAll(true);var cursor=panel.List.SelectedItem;var preview=main.PreviewInOtherPanel(panel);NavigationTests.Wait(preview.LoadingTask);main.UpdateLayout();check(preview.SelectionCount==3&&preview.VideoCountForTests==6,"mixed video/document selection retains the separate source-file strip");preview.ArrowForTests(Key.Right);NavigationTests.Wait(preview.LoadingTask);check(preview.SelectedPreviewIndex==1&&preview.VideoCountForTests==6,"source-strip arrows select the next video rather than its next frame");preview.SelectPreviewIndex(2);NavigationTests.Wait(preview.LoadingTask);check(preview.VideoCountForTests==0&&preview.SelectedPreviewPath==text,"selecting a document clears video controls");check((panel.List.SelectedItem as Entry)?.FullPath==preview.SelectedPreviewPath&&panel.PreviewEntries().Length==3,"preview navigation synchronizes the source cursor while preserving marks");preview.SelectPreviewIndex(0);NavigationTests.Wait(preview.LoadingTask);main.UpdateLayout();NextStageTests.Draw(main,Path.Combine(root,"mixed-selection-preview.png"));
            main.PreviewInOtherPanel(panel);main.SetPanelLayout("Single");panel.SetDetailExpanded(true);NavigationTests.Wait(panel.DetailLoadingTask);main.UpdateLayout();var bottom=panel.DetailPaneForTests;check(bottom.VideoCountForTests==6&&bottom.PictureHeightForTests>=60&&bottom.PictureFitsForTests,"bottom detail leaves visible space for the enlarged frame above its filmstrip");NextStageTests.Draw(main,Path.Combine(root,"bottom-video-preview.png"));main.Width=900;main.Height=700;main.UpdateLayout();NavigationTests.Wait(Task.Delay(80));main.UpdateLayout();NextStageTests.Draw(main,Path.Combine(root,"bottom-video-compact.png"));File.WriteAllText(Path.Combine(root,"compact-geometry.txt"),"picture="+bottom.PictureHeightForTests+" fits="+bottom.PictureFitsForTests+" "+panel.DetailGeometryForTests+" selected="+bottom.SelectedPreviewPath+" count="+bottom.SelectionCount);check(bottom.PictureHeightForTests>=40&&bottom.PictureFitsForTests&&panel.List.ActualHeight>=60,"compact main window keeps enlarged video picture inside bottom detail");NextStageTests.Draw(main,Path.Combine(root,"bottom-video-compact.png"));main.Close();main=null;
            File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
        }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(pane!=null)pane.DisposePreview();if(host!=null)host.Close();if(main!=null)main.Close();}
    }
    sealed class Approximate:System.Collections.Generic.IEqualityComparer<double>{public bool Equals(double a,double b){return Math.Abs(a-b)<.01;}public int GetHashCode(double value){return 0;}}
